raw.css:
:root {
  --color-primary: #c41e3a;
  --color-primary-dark: #8b1528;
  --color-primary-light: #f0e6e8;
  --color-accent-on-dark: #ffd6e0;
  --color-neutral-dark: #1a1a1a;
  --color-neutral-light: #f5f5f5;
  --color-text: #2c2c2c;
  --color-border: #e0e0e0;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
  --container-max-width: 900px;
  --container-padding: 1.5rem;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  line-height: 1.6;
  color: var(--color-text);
  background-color: #fff;
}

.container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: 0 var(--container-padding);
}

header.site-header {
  background-color: #fff;
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

header.site-header .container {
  display: flex;
  align-items: center;
  justify-content: center;
}

.logo {
  font-family: "Trebuchet MS", Verdana, sans-serif;
  font-size: clamp(1.25rem, 4vw, 1.75rem);
  font-weight: 800;
  color: var(--color-primary-dark);
  text-decoration: none;
  display: inline-block;
  transform: rotate(-2deg);
  text-shadow: 2px 2px 0 var(--color-primary);
  transition: transform 0.2s ease;
}

.logo:hover,
.logo:focus {
  transform: rotate(-2deg) scale(1.05);
  outline: 2px solid var(--color-primary);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .logo {
    transform: none;
    text-shadow: none;
  }
  .logo:hover,
  .logo:focus {
    transform: none;
  }
}

h1, h2, h3 {
  font-family: var(--font-serif);
  line-height: 1.3;
}

h1 {
  font-size: clamp(1.75rem, 6vw, 2.75rem);
  margin-bottom: var(--spacing-md);
}

h2 {
  font-size: clamp(1.5rem, 5vw, 2.25rem);
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
}

p {
  margin-bottom: var(--spacing-sm);
}

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
  transition: color 0.2s ease;
}

a:hover,
a:focus {
  color: var(--color-primary);
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

button,
input[type="submit"],
input[type="button"],
input[type="reset"] {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  min-height: 44px;
  min-width: 44px;
  border: none;
  border-radius: 4px;
  background-color: var(--color-primary-dark);
  color: #fff;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

button:hover,
input[type="submit"]:hover,
input[type="button"]:hover,
input[type="reset"]:hover {
  background-color: var(--color-primary);
}

button:focus,
input[type="submit"]:focus,
input[type="button"]:focus,
input[type="reset"]:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

button:active,
input[type="submit"]:active,
input[type="button"]:active,
input[type="reset"]:active {
  transform: scale(0.98);
}

form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="date"],
select,
textarea {
  font-family: var(--font-sans);
  font-size: 1rem;
  padding: 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: 4px;
  background-color: #fff;
  color: var(--color-text);
  min-height: 44px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="date"]:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 2px var(--color-primary-light);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

select {
  cursor: pointer;
  appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%232c2c2c' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 0.75rem center;
  background-size: 1.25rem;
  padding-right: 2.5rem;
}

footer.site-footer {
  background-color: var(--color-neutral-light);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-xl) 0;
  margin-top: var(--spacing-xl);
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-neutral-dark);
}

footer.site-footer p {
  margin-bottom: var(--spacing-xs);
}

footer.site-footer strong {
  color: var(--color-primary-dark);
}

.hero {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: #fff;
  padding: var(--spacing-xl) var(--container-padding);
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.hero h1 {
  color: #fff;
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.125rem;
  margin-bottom: var(--spacing-lg);
}

.hero a {
  color: var(--color-accent-on-dark);
}

.hero a:focus {
  outline: 2px solid var(--color-accent-on-dark);
}

section {
  padding: var(--spacing-lg) var(--container-padding);
}

section h2 {
  margin-top: 0;
}

.event-info {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
}

.info-card {
  background-color: var(--color-primary-light);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-primary-dark);
}

.info-card h3 {
  color: var(--color-primary-dark);
  margin-top: 0;
}

.info-card p {
  margin-bottom: 0;
  font-size: 1.125rem;
}

.mission {
  background-color: var(--color-neutral-light);
  padding: var(--spacing-lg) var(--container-padding);
  border-radius: 8px;
  margin-bottom: var(--spacing-lg);
}

.mission p {
  font-size: 1.0625rem;
  line-height: 1.8;
}

.form-group {
  display: flex;
  flex-direction: column;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--spacing-md);
}

@media (min-width: 601px) {
  .event-info {
    grid-template-columns: 1fr 1fr;
  }

  .form-row {
    grid-template-columns: 1fr 1fr;
  }

  section {
    padding: var(--spacing-xl) var(--container-padding);
  }

  .hero {
    padding: var(--spacing-xl) var(--container-padding);
    margin-bottom: var(--spacing-xl);
  }
}

@media (max-width: 600px) {
  html {
    font-size: 15px;
  }

  .hero {
    padding: var(--spacing-lg) var(--container-padding);
    margin-bottom: var(--spacing-lg);
  }

  .logo {
    white-space: nowrap;
  }
}

